local CreatePed, IsModelInCdimage, IsModelAPed = CreatePed, IsModelInCdimage, IsModelAPed
local IsPedAPlayer, NetworkGetPlayerIndexFromPed = IsPedAPlayer, NetworkGetPlayerIndexFromPed

-- default pedType 4 = PED_TYPE_CIVMALE
---@param model fx.Model|integer|string
---@param position vector3|vector4
---@param heading? number
---@param options? fx.PedCreateOptions
---@return fx.Ped?
statics.createRaw = function(model, position, heading, options)
  local hash = rt.hash(model)
  if not rt.requireLoaded("Ped.createRaw", hash, model) then return nil end
  local net = not (options and options.networked == false)
  local scriptHost = options and options.scriptHostPed or false
  local pedType = options and options.pedType or 4
  local h = CreatePed(pedType, hash, position.x, position.y, position.z, rt.heading(position, heading), net, scriptHost)
  local p = T.wrap(h)
  if p and net then rt.netIntent[p] = true end
  return p
end

---@param hash integer
---@return boolean
local function isPedModel(hash) return IsModelInCdimage(hash) and IsModelAPed(hash) end
statics.createAsync = rt.makeCreate("Ped.createAsync", isPedModel, statics.createRaw)

local wrapPlayer = rt.lazyWrap("Player")
---@param self fx.Ped
---@return fx.Player?
getters.player = function(self)
  local h = self.handle
  if not IsPedAPlayer(h) then return nil end
  return wrapPlayer(NetworkGetPlayerIndexFromPed(h))
end

-- Headshots: 26 regular slots and 1 transparent one; a handle of 0 means no free slot.
local RegisterPedheadshot, RegisterPedheadshotTransparent = RegisterPedheadshot, RegisterPedheadshotTransparent
local IsPedheadshotReady, IsPedheadshotValid, GetPedheadshotTxdString, UnregisterPedheadshot =
  IsPedheadshotReady, IsPedheadshotValid, GetPedheadshotTxdString, UnregisterPedheadshot

---@param self fx.Ped
---@param transparent? boolean
---@param timeoutMs? integer
---@return fx.Promise<string, integer>
methods.headshotAsync = function(self, transparent, timeoutMs)
  local id = (transparent and RegisterPedheadshotTransparent or RegisterPedheadshot)(self.handle)
  if id == 0 then return fx.Promise.reject("Ped:headshotAsync: no free headshot slot (release them with Ped.releaseHeadshot)") end
  ---@param err any
  ---@return fx.Promise rejected with err
  local function release(err)
    UnregisterPedheadshot(id) -- the caller never got the id: free the slot (26 for the whole client)
    return fx.Promise.reject(err)
  end
  return rt.waitUntil(tostring(self) .. ":headshotAsync", function()
    return IsPedheadshotReady(id) and IsPedheadshotValid(id)
  end, timeoutMs):next(function() return GetPedheadshotTxdString(id), id end, release)
end

---@param id integer
statics.releaseHeadshot = function(id) UnregisterPedheadshot(id) end

