-- errors without a position: the entry points (the methods, the proxies) raise them at the caller line
---@param msg string
local function fail(msg) error(msg, 0) end
---@param x number
---@return number
local function float(x) return x + 0.0 end

-- mirrored from src/enum-data.ts (fx.Enum.PedClothes, PedProps, PedFaceFeatures, PedOverlays)
---@alias fx.PedKeyId { [1]: string, [2]: integer } key, native id

---@type fx.PedKeyId[]
local CLOTHES = {
  { "mask", 1 }, { "arms", 3 }, { "legs", 4 }, { "bag", 5 }, { "shoes", 6 }, { "neck", 7 }, { "undershirt", 8 },
  { "armor", 9 }, { "decals", 10 }, { "top", 11 },
}
---@type fx.PedKeyId[]
local PROPS = { { "hat", 0 }, { "glasses", 1 }, { "ears", 2 }, { "watch", 6 }, { "bracelet", 7 } }
---@type fx.PedKeyId[]
