  { "noseWidth", 0 }, { "nosePeakHeight", 1 }, { "nosePeakLength", 2 }, { "noseBoneHeight", 3 }, { "nosePeakLowering", 4 },
  { "noseBoneTwist", 5 }, { "eyebrowHeight", 6 }, { "eyebrowDepth", 7 }, { "cheekBoneHeight", 8 }, { "cheekBoneWidth", 9 },
  { "cheekWidth", 10 }, { "eyeOpening", 11 }, { "lipThickness", 12 }, { "jawBoneWidth", 13 }, { "jawBoneLength", 14 },
  { "chinBoneHeight", 15 }, { "chinBoneLength", 16 }, { "chinBoneWidth", 17 }, { "chinDimple", 18 }, { "neckThickness", 19 },
}
---@type fx.PedKeyId[]
local OVERLAYS = {
  { "blemishes", 0 }, { "beard", 1 }, { "eyebrows", 2 }, { "ageing", 3 }, { "makeup", 4 }, { "blush", 5 }, { "complexion", 6 },
  { "sunDamage", 7 }, { "lipstick", 8 }, { "freckles", 9 }, { "chestHair", 10 }, { "bodyBlemishes", 11 },
  { "moreBodyBlemishes", 12 },
}
---@param list fx.PedKeyId[]
---@return table<string, integer>
local function index(list) local t = {} for _, e in ipairs(list) do t[e[1]] = e[2] end return t end
local COMP, PROP, FEATURE, OVERLAY = index(CLOTHES), index(PROPS), index(FACE), index(OVERLAYS)
-- colour type of SET_PED_HEAD_OVERLAY_COLOR: 1 hair colours, 2 makeup colours
---@type table<integer, integer>
local OVERLAY_COLOR = { [1] = 1, [2] = 1, [10] = 1, [4] = 2, [5] = 2, [8] = 2 }
local HEAD, HAIR = 0, 2

---@param map table<string, integer>
---@param key any Checked
---@param label string
---@param enum string fx.Enum name, for the error
---@return integer
local function idOf(map, key, label, enum)
  local id = map[key]
  if not id then fail(("%s: unknown key '%s' (see fx.Enum.%s)"):format(label, tostring(key), enum)) end
  return id
end

-- the collection natives need a recent game build: without them, the global indexes are used
---@type boolean?
local collections
---@param h integer
---@return boolean
local function hasCollections(h)
  if collections == nil then
    collections = GetPedDrawableVariationCollectionName ~= nil and (pcall(GetPedDrawableVariationCollectionName, h, 0))
  end
  return collections
end
---@param c any
---@return boolean
---@return_cast c string
local function named(c) return type(c) == "string" and c ~= "" end

---@param v fx.PedVariation|integer A number is a drawable with texture 0
---@param label string
---@return fx.PedVariation
local function variation(v, label)
  if type(v) == "number" then return { drawable = v } end
  if type(v) ~= "table" or type(v.drawable) ~= "number" then
    fail(("%s: expected a drawable index or { drawable, texture?, collection? }, got %s"):format(label, tostring(v)))
  end
  return v --[[@as fx.PedVariation]]
end

---@param h integer
---@param id integer
---@return fx.PedVariation
local function readComponent(h, id)
  ---@type fx.PedVariation
  local t = { drawable = GetPedDrawableVariation(h, id), texture = GetPedTextureVariation(h, id) }
  local palette = GetPedPaletteVariation(h, id)
  if palette and palette > 0 then t.palette = palette end
  if hasCollections(h) then
    local name = GetPedDrawableVariationCollectionName(h, id)
    if named(name) then t.collection, t.drawable = name, GetPedDrawableVariationCollectionLocalIndex(h, id) end
  end
  return t
end

---@param h integer
---@param id integer
---@param v any fx.PedVariation|integer, checked
---@param label string
local function writeComponent(h, id, v, label)
  v = variation(v, label)
  local d, tx, pal, coll = rt.int(v.drawable), rt.int(v.texture or 0), rt.int(v.palette or 0), v.collection
  if named(coll) and hasCollections(h) then
    if fx.debug and not IsPedCollectionComponentVariationValid(h, id, coll, d, tx) then
      fail(("%s: drawable %d / texture %d of '%s' does not exist on this model"):format(label, d, tx, coll))
    end
    SetPedCollectionComponentVariation(h, id, coll, d, tx, pal)
  else
    if fx.debug and not IsPedComponentVariationValid(h, id, d, tx) then
      fail(("%s: drawable %d / texture %d does not exist on this model"):format(label, d, tx))
    end
    SetPedComponentVariation(h, id, d, tx, pal)
  end
end

---@param h integer
---@param id integer
---@param coll? string
---@return integer
local function componentCount(h, id, coll)
  if named(coll) and hasCollections(h) then return GetNumberOfPedCollectionDrawableVariations(h, id, coll) end
  return GetNumberOfPedDrawableVariations(h, id)
end

---@param h integer
---@param id integer
---@param drawable integer
---@param coll? string
---@return integer
local function componentTextures(h, id, drawable, coll)
  drawable = rt.int(drawable)
  if named(coll) and hasCollections(h) then return GetNumberOfPedCollectionTextureVariations(h, id, coll, drawable) end
  return GetNumberOfPedTextureVariations(h, id, drawable)
end

-- every drawable of a component, as assignable values; gen9 (PS5 / Xbox Series) exclusives are left out
---@param h integer
---@param id integer
---@return fx.PedVariationItem[]
local function componentList(h, id)
  local out = {}
  local coll = hasCollections(h)
  for d = 0, GetNumberOfPedDrawableVariations(h, id) - 1 do
    if not (coll and IsPedComponentVariationGen9Exclusive and IsPedComponentVariationGen9Exclusive(h, id, d)) then
      ---@type fx.PedVariationItem
      local item = { drawable = d, textures = GetNumberOfPedTextureVariations(h, id, d) }
      if coll then
        local name = GetPedCollectionNameFromDrawable(h, id, d)
        if named(name) then item.collection, item.drawable = name, GetPedCollectionLocalIndexFromDrawable(h, id, d) end
      end
      out[#out + 1] = item
    end
  end
  return out
end

---@param h integer
---@param id integer
---@return fx.PedVariation|false variation false when the anchor point is empty
local function readProp(h, id)
  local d = GetPedPropIndex(h, id)
  if d == -1 then return false end
  ---@type fx.PedVariation
  local t = { drawable = d, texture = GetPedPropTextureIndex(h, id) }
  if hasCollections(h) then
    local name = GetPedPropCollectionName(h, id)
    if named(name) then t.collection, t.drawable = name, GetPedPropCollectionLocalIndex(h, id) end
  end
  return t
end

---@param h integer
---@param id integer
---@param coll? string
---@return integer
local function propCount(h, id, coll)
  if named(coll) and hasCollections(h) then return GetNumberOfPedCollectionPropDrawableVariations(h, id, coll) end
  return GetNumberOfPedPropDrawableVariations(h, id)
end

---@param h integer
---@param id integer
---@param drawable integer
---@param coll? string
---@return integer
local function propTextures(h, id, drawable, coll)
  drawable = rt.int(drawable)
  if named(coll) and hasCollections(h) then return GetNumberOfPedCollectionPropTextureVariations(h, id, coll, drawable) end
  return GetNumberOfPedPropTextureVariations(h, id, drawable)
end

---@param h integer
---@param id integer
---@param v any fx.PedVariation|integer|false, checked
---@param label string
local function writeProp(h, id, v, label)
  if v == false or v == -1 then ClearPedProp(h, id); return end
  v = variation(v, label)
  local d, tx, coll = rt.int(v.drawable), rt.int(v.texture or 0), v.collection
  if fx.debug then
    local n = propCount(h, id, coll)
    if d < 0 or d >= n or tx < 0 or tx >= propTextures(h, id, d, coll) then
      fail(("%s: drawable %d / texture %d does not exist on this model"):format(label, d, tx))
    end
  end
  if named(coll) and hasCollections(h) then
    SetPedCollectionPropIndex(h, id, coll, d, tx, true)
  else
    SetPedPropIndex(h, id, d, tx, true)
  end
end

---@param h integer
---@param id integer
---@return fx.PedVariationItem[]
local function propList(h, id)
  local out = {}
  local coll = hasCollections(h)
  for d = 0, GetNumberOfPedPropDrawableVariations(h, id) - 1 do
    ---@type fx.PedVariationItem
    local item = { drawable = d, textures = GetNumberOfPedPropTextureVariations(h, id, d) }
    if coll then
      local name = GetPedCollectionNameFromProp(h, id, d)
      if named(name) then item.collection, item.drawable = name, GetPedCollectionLocalIndexFromProp(h, id, d) end
    end
    out[#out + 1] = item
  end
  return out
end

---@param h integer
---@return fx.PedClothesData
local function getClothes(h)
  local t = {}
  for _, c in ipairs(CLOTHES) do t[c[1]] = readComponent(h, c[2]) end
  return t
end

---@param h integer
---@param t fx.PedClothesData
local function setClothes(h, t)
  for k in pairs(t) do idOf(COMP, k, "clothes", "PedClothes") end
  for _, c in ipairs(CLOTHES) do
    if t[c[1]] ~= nil then writeComponent(h, c[2], t[c[1]], "ped.clothes." .. c[1]) end
  end
end

---@param h integer
---@return fx.PedPropsData
local function getProps(h)
  local t = {}
  for _, p in ipairs(PROPS) do t[p[1]] = readProp(h, p[2]) end
  return t
end

---@param h integer
---@param t fx.PedPropsData
local function setProps(h, t)
  for k in pairs(t) do idOf(PROP, k, "props", "PedProps") end
  for _, p in ipairs(PROPS) do
    if t[p[1]] ~= nil then writeProp(h, p[2], t[p[1]], "ped.props." .. p[1]) end
  end
end

-- head blend (freemode models): GET_PED_HEAD_BLEND_DATA fills a struct of 10 fields of 8 bytes
---@type string[]
local HEAD_BLEND_KEYS = { "shapeFirst", "shapeSecond", "shapeThird", "skinFirst", "skinSecond", "skinThird",
  "shapeMix", "skinMix", "thirdMix" }
---@type table<string, true>
local isHeadBlendKey = {}
for _, k in ipairs(HEAD_BLEND_KEYS) do isHeadBlendKey[k] = true end

---@param h integer
---@return fx.PedHeadBlend?
local function getHeadBlend(h)
  local buffer = string_rep("\0", 80)
  local found = InvokeNative(0x2746BD9D88C5C5D0, h, buffer, ReturnResultAnyway())
  if not found or found == 0 then return nil end
  local t, values = {}, { string_unpack("<i4xxxxi4xxxxi4xxxxi4xxxxi4xxxxi4xxxxfxxxxfxxxxfxxxx", buffer) }
  for i, k in ipairs(HEAD_BLEND_KEYS) do t[k] = values[i] end
  return t
end

---@param h integer
---@param v any fx.PedHeadBlend, checked
local function setHeadBlend(h, v)
  if type(v) ~= "table" then fail("headBlend: expected a table") end
  for k in pairs(v) do
    if not isHeadBlendKey[k] then fail(("headBlend: unknown key '%s'"):format(tostring(k))) end
  end
  local cur = getHeadBlend(h) or {}
  ---@param k string
  ---@return integer
  local function int(k) return rt.int(v[k] or cur[k] or 0) end
  ---@param k string
  ---@return number
  local function mix(k) return float(v[k] or cur[k] or 0.0) end
  SetPedHeadBlendData(h, int("shapeFirst"), int("shapeSecond"), int("shapeThird"), int("skinFirst"), int("skinSecond"),
    int("skinThird"), mix("shapeMix"), mix("skinMix"), mix("thirdMix"), false)
end

---@param h integer
---@return fx.PedFaceData
local function getFace(h)
  local t = { eyeColor = GetPedEyeColor(h) }
  for _, f in ipairs(FACE) do t[f[1]] = GetPedFaceFeature(h, f[2]) end
  return t
end

---@param h integer
---@param t fx.PedFaceData
local function setFace(h, t)
  for k, v in pairs(t) do
    if k == "eyeColor" then
      SetPedEyeColor(h, rt.int(v))
    else
      local id = idOf(FEATURE, k, "face", "PedFaceFeatures")
      if type(v) ~= "number" then fail(("face.%s: expected a number from -1.0 to 1.0, got %s"):format(k, tostring(v))) end
      SetPedFaceFeature(h, id, float(v))
    end
  end
end

---@type table<string, true>
local HAIR_KEYS = { style = true, texture = true, collection = true, palette = true, color = true, highlight = true }

---@param h integer
---@return fx.PedHairData
local function getHair(h)
  local c = readComponent(h, HAIR)
  return { style = c.drawable, texture = c.texture, collection = c.collection, color = GetPedHairColor(h),
    highlight = GetPedHairHighlightColor(h) }
end

-- a new hair drawable resets the tint: the colours are applied after it
---@param h integer
---@param t any fx.PedHairData|integer, checked
local function setHair(h, t)
  if type(t) == "number" then t = { style = t } end
  if type(t) ~= "table" then fail("hair: expected a table") end
  for k in pairs(t) do
    if not HAIR_KEYS[k] then fail(("hair: unknown key '%s'"):format(tostring(k))) end
  end
  local color, highlight = t.color, t.highlight
  if t.style ~= nil or t.texture ~= nil or t.collection ~= nil then
    color, highlight = color or GetPedHairColor(h), highlight or GetPedHairHighlightColor(h)
    local cur = readComponent(h, HAIR)
    local coll = t.collection
    if coll == nil and t.style == nil then coll = cur.collection end
    writeComponent(h, HAIR, { drawable = t.style or cur.drawable, texture = t.texture or 0, collection = coll,
      palette = t.palette }, "ped.hair")
  end
  if color ~= nil or highlight ~= nil then
    local c = rt.int(color or GetPedHairColor(h))
    SetPedHairTint(h, c, rt.int(highlight or GetPedHairHighlightColor(h) or c))
  end
end

-- the natives use 255 for no overlay
---An overlay as read: every field is set.
---@class fx.PedOverlayRead : fx.PedOverlay
---@field style integer
---@field opacity number
---@field color integer
---@field secondColor integer

---@param h integer
---@param id integer
---@return fx.PedOverlayRead
local function getOverlay(h, id)
  local ok, value, _, first, second, opacity = GetPedHeadOverlayData(h, id)
  if not ok or ok == 0 then return { style = -1, opacity = 0.0, color = 0, secondColor = 0 } end
  return { style = value == 255 and -1 or value, opacity = opacity, color = first, secondColor = second }
end

---@param h integer
---@param id integer
---@param v any fx.PedOverlay|integer|false, checked
---@param label string
local function setOverlay(h, id, v, label)
  if v == false then v = { style = -1 } elseif type(v) == "number" then v = { style = v } end
  if type(v) ~= "table" then fail(("%s: expected a style index or { style, opacity?, color?, secondColor? }"):format(label)) end
  local cur = getOverlay(h, id)
  local style = rt.int(v.style or cur.style)
  local opacity = v.opacity or ((cur.style == -1 or cur.opacity == 0) and 1.0 or cur.opacity)
  SetPedHeadOverlay(h, id, style == -1 and 255 or style, float(opacity))
  local colorType = OVERLAY_COLOR[id]
  if colorType and (v.color ~= nil or v.secondColor ~= nil or cur.style == -1) then
    local color = rt.int(v.color or cur.color or 0)
    SetPedHeadOverlayColor(h, id, colorType, color, rt.int(v.secondColor or cur.secondColor or color))
  end
end

---@param h integer
---@return fx.PedOverlaysData
local function getOverlays(h)
  local t = {}
  for _, o in ipairs(OVERLAYS) do t[o[1]] = getOverlay(h, o[2]) end
  return t
end

---@param h integer
---@param t fx.PedOverlaysData
local function setOverlays(h, t)
  for k in pairs(t) do idOf(OVERLAY, k, "overlays", "PedOverlays") end
  for _, o in ipairs(OVERLAYS) do
    if t[o[1]] ~= nil then setOverlay(h, o[2], t[o[1]], "ped.overlays." .. o[1]) end
  end
end

---@param x integer|string
---@return integer
local function hash(x) if type(x) == "string" then return GetHashKey(x) end return rt.int(x) end

---@param h integer
---@return fx.PedTattoo[]
local function getTattoos(h)
  local out = {}
  for _, d in ipairs(GetPedDecorations(h) or {}) do out[#out + 1] = { collection = d[1], overlay = d[2] } end
  return out
end

---@param v fx.PedTattoo Hashes or names
---@param label string
---@return integer collection, integer overlay
local function tattoo(v, label)
  if type(v) ~= "table" or v.collection == nil or v.overlay == nil then
    fail(("%s: expected { collection, overlay }, got %s"):format(label, tostring(v)))
  end
  return hash(v.collection), hash(v.overlay)
end

---@param h integer
---@param list fx.PedTattoo[] Checked
local function setTattoos(h, list)
  if type(list) ~= "table" then fail("tattoos: expected a list of { collection, overlay }") end
  ---@type integer[][]
  local pairsList = {}
  for i, v in ipairs(list) do pairsList[i] = { tattoo(v, "tattoos[" .. i .. "]") } end
  ClearPedDecorations(h)
  for _, p in ipairs(pairsList) do AddPedDecorationFromHashes(h, p[1], p[2]) end
end

---@param self fx.Ped
---@param h integer
---@param what string Method name, for the error
local function requireControl(self, h, what)
  if fx.debug and NetworkGetEntityIsNetworked(h) and not NetworkHasControlOfEntity(h) then
    error(("%s:%s: this client does not control the ped (use %sAsync)"):format(tostring(self), what, what), 4)
  end
end

---@param self fx.Ped
---@param groups? string[]
---@param all string[]
---@param get table<string, fun(h: integer): any>
---@param what string Method name, for the errors
---@return table
local function readGroups(self, groups, all, get, what)
  local h = self.handle
  local t = { model = GetEntityModel(h) }
  if groups == nil then groups = all end
  if type(groups) ~= "table" then error(("ped:%s: groups must be a list"):format(what), 3) end
  for _, g in ipairs(groups) do
    if not get[g] then error(("ped:%s: unknown group '%s' (%s)"):format(what, tostring(g), table.concat(all, ", ")), 3) end
    t[g] = get[g](h)
  end
  return t
end

---@param self fx.Ped
---@param t any Checked
---@param all string[]
---@param set table<string, fun(h: integer, v: any)>
---@param what string Method name, for the errors
---@return fx.Ped
local function writeGroups(self, t, all, set, what)
  if type(t) ~= "table" then error(("ped:%s: expected a table"):format(what), 3) end
  local h = self.handle
  requireControl(self, h, what)
  for k in pairs(t) do
    if k ~= "model" and not set[k] then
      error(("ped:%s: unknown group '%s' (%s)"):format(what, tostring(k), table.concat(all, ", ")), 3)
    end
  end
  for _, g in ipairs(all) do
    if t[g] ~= nil then
      local ok, err = pcall(set[g], h, t[g])
      if not ok then error(("%s:%s: %s"):format(tostring(self), what, tostring(err)), 3) end
    end
  end
  return self
end

---@type fx.PedOutfitGroup[]
local OUTFIT = { "clothes", "props" }
---@type table<string, fun(h: integer): any>
local OUTFIT_GET = { clothes = getClothes, props = getProps }
---@type table<string, fun(h: integer, v: any)>
local OUTFIT_SET = { clothes = setClothes, props = setProps }
-- the head blend first: it resets what depends on the head
---@type fx.PedAppearanceGroup[]
local APPEARANCE = { "headBlend", "face", "head", "hair", "overlays", "tattoos" }
---@type table<string, fun(h: integer): any>
local APPEARANCE_GET = { headBlend = getHeadBlend, face = getFace, hair = getHair, overlays = getOverlays, tattoos = getTattoos,
  ---@param h integer
  ---@return fx.PedVariation
  head = function(h) return readComponent(h, HEAD) end }
---@type table<string, fun(h: integer, v: any)>
local APPEARANCE_SET = { headBlend = setHeadBlend, face = setFace, hair = setHair, overlays = setOverlays, tattoos = setTattoos,
  ---@param h integer
  ---@param v any fx.PedVariation|integer, checked
  head = function(h, v) writeComponent(h, HEAD, v, "head") end }

---@param self fx.Ped
---@param groups? fx.PedOutfitGroup[]
---@return fx.PedOutfit
methods.getOutfit = function(self, groups) return readGroups(self, groups, OUTFIT, OUTFIT_GET, "getOutfit") end

---@param self fx.Ped
---@param outfit fx.PedOutfit
---@return fx.Ped
methods.setOutfit = function(self, outfit)
  if fx.debug and type(outfit) == "table" and outfit.model and outfit.model ~= GetEntityModel(self.handle) then
    error(("%s:setOutfit: this outfit was made for another model (%s)"):format(tostring(self), tostring(outfit.model)), 2)
  end
  return writeGroups(self, outfit, OUTFIT, OUTFIT_SET, "setOutfit")
end

-- the drawables are streamed in before they are put on: no ped in underwear for a few frames
---@param h integer
---@param outfit fx.PedOutfit
local function preload(h, outfit)
  local coll = hasCollections(h)
  for key, v in pairs(type(outfit.clothes) == "table" and outfit.clothes or {}) do
    local id = COMP[key]
    if id and v ~= false then
      v = variation(v, "ped.clothes." .. key)
      if named(v.collection) and coll then
        SetPedCollectionPreloadVariationData(h, id, v.collection, rt.int(v.drawable), rt.int(v.texture or 0))
      else
        SetPedPreloadVariationData(h, id, rt.int(v.drawable), rt.int(v.texture or 0))
      end
    end
  end
  for key, v in pairs(type(outfit.props) == "table" and outfit.props or {}) do
    local id = PROP[key]
    if id and v ~= false and v ~= -1 then
      v = variation(v, "ped.props." .. key)
      if named(v.collection) and coll then
        SetPedCollectionPreloadPropData(h, id, v.collection, rt.int(v.drawable), rt.int(v.texture or 0))
      else
        SetPedPreloadPropData(h, id, rt.int(v.drawable), rt.int(v.texture or 0))
      end
    end
  end
end

---@param self fx.Ped
---@param outfit fx.PedOutfit
---@param timeoutMs? integer
---@return fx.Promise<fx.Ped>
methods.setOutfitAsync = function(self, outfit, timeoutMs)
  if type(outfit) ~= "table" then return rt.fail(tostring(self) .. ":setOutfitAsync: expected a table") end
  local loaded = false
  ---@param p fx.Ped
  ---@return fx.Ped
  local function apply(p) return p:setOutfit(outfit) end
  return self:takeControlAsync(timeoutMs):next(function(p)
    local h = p.handle
    preload(h, outfit)
    loaded = true
    return rt.waitUntil(tostring(p) .. ":setOutfitAsync", function()
      return HasPedPreloadVariationDataFinished(h) and HasPedPreloadPropDataFinished(h)
    end, timeoutMs, p)
  end):next(apply):finally(function()
    if loaded then ReleasePedPreloadVariationData(self.handle); ReleasePedPreloadPropData(self.handle) end
  end)
end

---@param self fx.Ped
---@param groups? fx.PedAppearanceGroup[]
---@return fx.PedAppearance
methods.getAppearance = function(self, groups) return readGroups(self, groups, APPEARANCE, APPEARANCE_GET, "getAppearance") end
---@param self fx.Ped
---@param appearance fx.PedAppearance
---@return fx.Ped
methods.setAppearance = function(self, appearance) return writeGroups(self, appearance, APPEARANCE, APPEARANCE_SET, "setAppearance") end
---@param self fx.Ped
---@param appearance fx.PedAppearance
---@param timeoutMs? integer
---@return fx.Promise<fx.Ped>
methods.setAppearanceAsync = function(self, appearance, timeoutMs)
  return self:takeControlAsync(timeoutMs):next(function(p) return p:setAppearance(appearance) end)
end

