---@param a fx.PedTattoo
---@param c integer
---@param o integer
---@return boolean
local function sameTattoo(a, c, o) return a.collection == c and a.overlay == o end
getters.tattoos = proxy("tattoos", {
  ---@param p fx.PedTattoosProxy
  ---@param collection integer|string
  ---@param overlay integer|string
  ---@return fx.PedTattoosProxy
  add = function(p, collection, overlay)
    local h = handleOf(p)
    local c, o = tattoo({ collection = collection, overlay = overlay }, "ped.tattoos:add")
    AddPedDecorationFromHashes(h, c, o)
    return p
  end,
  ---@param p fx.PedTattoosProxy
  ---@param collection integer|string
  ---@param overlay integer|string
  ---@return fx.PedTattoosProxy
  remove = function(p, collection, overlay)
    local h = handleOf(p)
    local c, o = tattoo({ collection = collection, overlay = overlay }, "ped.tattoos:remove")
    local keep = {}
    for _, t in ipairs(getTattoos(h)) do if not sameTattoo(t, c, o) then keep[#keep + 1] = t end end
    setTattoos(h, keep)
    return p
  end,
  ---@param p fx.PedTattoosProxy
  ---@param collection integer|string
  ---@param overlay integer|string
  ---@return boolean
  has = function(p, collection, overlay)
    local c, o = tattoo({ collection = collection, overlay = overlay }, "ped.tattoos:has")
    for _, t in ipairs(getTattoos(handleOf(p))) do if sameTattoo(t, c, o) then return true end end
    return false
  end,
  ---@param p fx.PedTattoosProxy
  ---@return fx.PedTattoosProxy
  clear = function(p) ClearPedDecorations(handleOf(p)); return p end,
  ---@param p fx.PedTattoosProxy
  ---@return fx.PedTattoo[]
  get = function(p) return getTattoos(handleOf(p)) end,
  ---@param p fx.PedTattoosProxy
  ---@param list fx.PedTattoo[]
  ---@return fx.PedTattoosProxy
  set = function(p, list) setTattoos(handleOf(p), list); return p end,
}, function(_, k) fail(("ped.tattoos: no field '%s' (use :get(), :add(), :remove()...)"):format(tostring(k))) end,
  function(_, k) fail(("ped.tattoos: cannot assign '%s' (use :set(list))"):format(tostring(k))) end)

end

